export class BadgeEditor {
  validateBadge(name: string): boolean {
    if (name.length === 0) {
      this.errorMessage = 'required badge name'
      return false
    }
    this.errorMessage = ''
    return true
  }
}

sources.PacketDecoder.ts:
export class PacketDecoder {
  decodePacket(bytes: Uint8Array): object {
    if (bytes.length < 2) {
      return { error: 'invalid packet' }
    }
    return { value: bytes[0] }
  }
}

